#!/usr/bin/env node
// Pull README / docs files from GitHub repos into the `docs` collection.
//
//   npm run sync:docs                 # uses src/data/github.json
//   GITHUB_TOKEN=ghp_xxx npm run sync:docs
//
// Output: src/content/docs/<section>/repos/<repo>[--<file>].md
// Generated files carry `source:` frontmatter — never edit them by hand,
// edit the README in the source repo instead.
import { mkdir, writeFile, readFile } from "node:fs/promises";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "..");
const config = JSON.parse(await readFile(path.join(root, "src/data/github.json"), "utf8"));
const token = process.env.GITHUB_TOKEN;
const headers = { accept: "application/vnd.github.raw+json", "user-agent": "cpr-blog-docs-sync" };
if (token) headers.authorization = `Bearer ${token}`;

const yaml = (s) => JSON.stringify(s); // JSON strings are valid YAML scalars

/** Turn relative links/images into absolute GitHub URLs so they work on the blog. */
function absolutise(md, repo, ref, filePath) {
	const dir = path.posix.dirname(filePath);
	const blob = `https://github.com/${repo}/blob/${ref}/`;
	const raw = `https://raw.githubusercontent.com/${repo}/${ref}/`;
	return md.replace(
		/(!?)\[([^\]]*)\]\((?!https?:|#|mailto:)([^)\s]+)([^)]*)\)/g,
		(_m, bang, text, url, rest) => {
			const resolved = path.posix.normalize(path.posix.join(dir, url)).replace(/^\.\//, "");
			return `${bang}[${text}](${bang ? raw : blob}${resolved}${rest})`;
		},
	);
}

let ok = 0;
let failed = 0;
for (const repo of config.repos) {
	if (!repo.section || !repo.docs?.length) continue;
	const full = `${config.org}/${repo.name}`;
	for (const file of repo.docs) {
		const ref = repo.ref ?? "main";
		const url = `https://api.github.com/repos/${full}/contents/${file}?ref=${ref}`;
		try {
			const res = await fetch(url, { headers });
			if (!res.ok) throw new Error(`HTTP ${res.status}`);
			let body = await res.text();

			// Use the first H1 as the page title, and drop it from the body.
			const h1 = body.match(/^#\s+(.+)$/m);
			const title = h1?.[1].trim() ?? `${repo.label} — ${file}`;
			if (h1) body = body.replace(h1[0], "").trimStart();
			body = absolutise(body, full, ref, file);

			const base =
				file === "README.md"
					? repo.name
					: `${repo.name}--${file.replace(/\.mdx?$/, "").replace(/[\/]/g, "-")}`;
			const outDir = path.join(root, "src/content/docs", repo.section, "repos");
			await mkdir(outDir, { recursive: true });
			const frontmatter = [
				"---",
				`# GENERATED by scripts/sync-github-docs.mjs — edit ${full}/${file} instead.`,
				`title: ${yaml(title)}`,
				`description: ${yaml(`${repo.label} documentation, synced from GitHub.`)}`,
				`section: ${yaml(repo.section)}`,
				"order: 50",
				"source:",
				`  repo: ${yaml(full)}`,
				`  path: ${yaml(file)}`,
				`  ref: ${yaml(ref)}`,
				`  syncedAt: ${new Date().toISOString()}`,
				"---",
				"",
			].join("\n");
			const outFile = path.join(outDir, `${base}.md`);
			// Skip unchanged files so the scheduled workflow only opens a PR on real changes.
			const previous = await readFile(outFile, "utf8").catch(() => "");
			const stripSyncedAt = (s) => s.replace(/^\s*syncedAt:.*$/m, "");
			if (stripSyncedAt(previous) === stripSyncedAt(frontmatter + body)) {
				console.log(`= ${full}/${file} (unchanged)`);
				ok++;
				continue;
			}
			await writeFile(outFile, frontmatter + body);
			console.log(`✓ ${full}/${file}`);
			ok++;
		} catch (err) {
			console.warn(`✗ ${full}/${file}: ${err.message}`);
			failed++;
		}
	}
}
console.log(`\nSynced ${ok} file(s), ${failed} failed.`);
// Failing to sync must not break a build: keep the last committed copy.
